global.d_listen = steam_networking_sockets_create_listen_socket_ip(27902);
global.d_conn = steam_networking_sockets_connect_by_ip_address("127.0.0.1", 27902);
show_debug_message("gametest: listen " + string(global.d_listen) + " conn " + string(global.d_conn) + " err " + string(steam_api_last_error()));
return 1;

show_debug_message("gametest: control callbacks " + string(gametest_event_count("ctl")));
var i = steam_networking_sockets_get_connection_info(global.d_conn);
show_debug_message("gametest: conn info " + (is_struct(i) ? json_stringify(i) : string(i)));
return gametest_event_count("ctl");
